{"description":"Try direct HTTP from python urllib to OGC API","command":"python3 - <<'EOF'
import urllib.request, json
url="https://api.weather.gc.ca/collections/climate-daily/items?bbox=-75.4,45.3,-75.2,45.6&limit=100&offset=64600&f=json"
try:
    r=urllib.request.urlopen(url, timeout=20)
    d=json.load(r)
    s={}
    for f in d['features']:
        p=f['properties']
        k=(p['STN_ID'], p['CLIMATE_IDENTIFIER'], p['STATION_NAME'])
        s[k]=s.get(k,0)+1
    print('status', r.status, 'distinct:', len(s))
    for x,c in sorted(s.items()): print(c,x)
except Exception as e:
    print('ERR', type(e).__name__, e)
EOF"}

