d=json.load(open('/workspace/fetched/wgc_b155.json'))
s={}
for f in d['features']:
    p=f['properties']
    k=(p['STN_ID'], p['CLIMATE_IDENTIFIER'], p['STATION_NAME'])
    s[k]=s.get(k,0)+1
print(len(s))
for x,c in sorted(s.items()): print(c,x)
""}

